.dashboard-home {
  --a-home-shared-frame-background: #f1f6fc;
  --a-home-shared-frame-border: rgba(195, 212, 235, 0.24);
  --a-home-shared-frame-radius: 8px;
  --a-home-shared-frame-shadow: var(--a-home-theme-shadow, none);
  --dashboard-bg: #e7eff5;
  --dashboard-border: rgba(82, 103, 122, 0.22);
  --dashboard-card: rgba(255, 255, 255, 0.86);
  --dashboard-shadow: 0 12px 28px rgba(47, 61, 76, 0.12);
  --dashboard-accent: #2f6fed;
  --dashboard-accent-soft: rgba(47, 111, 237, 0.1);
  --dashboard-green: #2d8a63;
  --dashboard-amber: #b56a18;
  --dashboard-purple: #6f2cff;
  --dashboard-purple-soft: rgba(111, 44, 255, 0.22);
  --dashboard-text: #203040;
  --dashboard-muted: #617181;
  --dashboard-node-radius: 8px;
  --dashboard-control-radius: 6px;
  --dashboard-shared-row-height: clamp(268px, 21.8vw, 344px);
  --dashboard-shared-gap: 10px;
  --dashboard-shared-margin-bottom: 16px;
  --dashboard-front-stack-gap: 16px;
  --dashboard-shared-padding: 9px 11px;
  --dashboard-planning-gap: 10px;
  --dashboard-planning-margin-bottom: 16px;
  --dashboard-planning-section-min-height: 164px;
  --dashboard-planning-panel-padding: 10px;
  --dashboard-planning-header-min-height: 36px;
  --dashboard-planning-header-margin-bottom: 8px;
  --dashboard-planning-heading-icon-size: 30px;
  --dashboard-planning-control-height: 31px;
  --dashboard-planning-control-padding: 4px 11px;
  --dashboard-planning-period-gap: 8px;
  --dashboard-planning-period-padding: 9px 10px;
  --dashboard-planning-period-header-min-height: 41px;
  --dashboard-planning-period-header-margin-bottom: 9px;
  --dashboard-planning-period-icon-size: 39px;
  --dashboard-planning-period-reset-size: 39px;
  --dashboard-planning-list-height: 278px;
  --dashboard-planning-item-height: 58px;
  --dashboard-planning-item-padding: 5px;
  --dashboard-progress-card-padding: 9px 10px;
  --dashboard-progress-item-padding: 7px 8px 6px;
  --dashboard-progress-item-icon-size: 42px;
  /* 固定底部工具栏不参与文档流；真实滚动留白由末尾 spacer 提供。 */
  --dashboard-scroll-toolbar-clearance: 88px;
  padding: 24px;
  scroll-padding-bottom: calc(24px + var(--dashboard-scroll-toolbar-clearance));
  background: var(--dashboard-bg);
  min-height: 100%;
  color: var(--dashboard-text);
  position: relative;
  /* 禁止 Chromium 把主页末尾占位或动态任务节点选作滚动锚点。
     否则首次重命名、删除、新建等 DOM 高度变化会自动改写 scrollTop。 */
  overflow-anchor: none;
}
/*
 * THEME-SKIN-TOKENS: light
 * Shared semantic palette. Six-module migration must consume these tokens
 * instead of introducing new per-module light-theme color literals.
 */
.dashboard-home.dashboard-home--skin-default:not(.dashboard-home--resolved-dark) {
  --a-home-shared-frame-background: #f1f6fc;
  --a-home-shared-frame-border: rgba(195, 212, 235, 0.24);
  --a-home-shared-frame-radius: 8px;
  --a-home-shared-frame-shadow: var(--a-home-theme-shadow);
  --a-home-theme-page: #e7eff5;
  --a-home-theme-module: linear-gradient(160deg, rgba(250, 252, 255, 0.98), rgba(233, 241, 253, 0.94));
  --a-home-theme-surface: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(244, 248, 255, 0.9));
  --a-home-theme-surface-raised: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(246, 249, 255, 0.94));
  --a-home-theme-border: rgba(195, 212, 235, 0.24);
  --a-home-theme-highlight: rgba(255, 255, 255, 0.76);
  --a-home-theme-text: #17365d;
  --a-home-theme-muted: #617181;
  --a-home-theme-control: linear-gradient(180deg, rgba(247, 250, 255, 0.98), rgba(232, 240, 252, 0.94));
  --a-home-theme-control-text: #17365d;
  --a-home-theme-active: linear-gradient(180deg, rgba(255, 250, 247, 0.98), rgba(252, 239, 230, 0.95));
  --a-home-theme-active-text: #24547b;
  --a-home-theme-focus: #2f6fed;
  --a-home-theme-success: #2d8a63;
  --a-home-theme-warning: #b56a18;
  --a-home-theme-danger: #a83f3f;
  --a-home-theme-danger-text: #fff8f6;
  --a-home-theme-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.76), 0 -1px 0 0 rgba(167, 194, 226, 0.24);
  --a-home-theme-decoration-opacity: 0.14;
}

