  .dashboard-home .dashboard-home__shared-modules {
    grid-template-columns: none !important;
    grid-template-rows: var(--dashboard-shared-row-height) !important;
    grid-auto-flow: column;
    grid-auto-columns: minmax(288px, min(420px, calc(100vw - 48px)));
    grid-auto-rows: unset !important;
    align-items: stretch;
    max-width: 100%;
    padding: 0 2px 8px;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scroll-snap-type: x proximity;
    scrollbar-gutter: stable;
    touch-action: pan-x pan-y;
  }

  .dashboard-home .dashboard-home__shared-modules > .dashboard-home__shared-module {
    grid-column: auto !important;
    grid-row: 1;
    width: 100%;
    min-width: 0;
    scroll-snap-align: start;
    scroll-snap-stop: normal;
  }

  .dashboard-home.dashboard-home--density-compact .dashboard-home__shared-modules {
    grid-template-rows: clamp(248px, 78vw, 316px) !important;
  }

  .dashboard-home.dashboard-home--density-standard .dashboard-home__shared-modules {
    grid-template-rows: clamp(268px, 84vw, 344px) !important;
  }

  .dashboard-home.dashboard-home--density-relaxed .dashboard-home__shared-modules {
