  color: var(--dashboard-muted);
  font-size: 12px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__shared-module-settings {
  position: absolute;
  top: min(6px, 1.3cqw);
  right: min(6px, 1.3cqw);
  display: grid;
  place-items: center;
  width: min(24px, 5.2cqw);
  height: min(24px, 5.2cqw);
  border: 1px solid rgba(82, 103, 122, 0.18);
  border-radius: min(7px, 1.5cqw);
  background: rgba(255, 255, 255, 0.94);
  color: var(--dashboard-muted);
  font-size: min(13px, 2.8cqw);
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease;
}

.dashboard-home__shared-module:hover .dashboard-home__shared-module-settings,
.dashboard-home__shared-module:focus-within .dashboard-home__shared-module-settings {
  opacity: 1;
  pointer-events: auto;
}

.dashboard-home__shared-module-popup {
  position: fixed;
  z-index: 10000;
  container-type: inline-size;
  max-height: min(560px, calc(100vh - 24px));
  display: flex;
  flex-direction: column;
  gap: min(8px, 2.22cqw);
  padding: min(10px, 2.78cqw);
  border: 2px solid rgba(82, 103, 122, 0.22);
  border-radius: var(--dashboard-node-radius);
  background: rgba(247, 250, 252, 0.98);
  box-shadow: 0 18px 38px rgba(32, 48, 64, 0.22);
  color: var(--dashboard-text);
}

.dashboard-home__shared-module-popup-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: min(8px, 2.22cqw);
  align-items: center;
  min-height: min(34px, 9.45cqw);
  padding: min(4px, 1.12cqw) min(6px, 1.67cqw);
  border: 1px solid rgba(82, 103, 122, 0.14);
  border-radius: var(--dashboard-node-radius);
  background: rgba(255, 255, 255, 0.9);
}

.dashboard-home__shared-module-popup-header strong {
  min-width: 0;
  font-size: min(14px, 3.9cqw);
  line-height: 1.15;
}

.dashboard-home__shared-module-popup-actions {
  display: flex;
  gap: min(5px, 1.4cqw);
}

.dashboard-home__shared-module-popup-actions .dashboard-home__square-action {
  width: min(28px, 7.78cqw);
  min-width: min(28px, 7.78cqw);
  height: min(28px, 7.78cqw);
  min-height: min(28px, 7.78cqw);
  padding: 0;
}

.dashboard-home__shared-module-popup-actions .dashboard-home__square-action-icon {
  font-size: min(11px, 3.05cqw);
}

.dashboard-home__shared-module-popup-actions .dashboard-home__square-action-label {
  font-size: min(9px, 2.5cqw);
}

.dashboard-home__shared-module-popup-body {
  display: flex;
  flex-direction: column;
  gap: min(8px, 2.22cqw);
  overflow: auto;
}

.dashboard-home__shared-setting-row {
  display: grid;
  grid-template-columns: min(96px, 26.67cqw) minmax(0, 1fr);
  gap: min(8px, 2.22cqw);
  align-items: center;
}

.dashboard-home__shared-setting-row > span {
  min-width: 0;
  color: var(--dashboard-muted);
  font-size: min(12px, 3.34cqw);
  font-weight: 700;
  line-height: 1.15;
}

.dashboard-home__shared-setting-row input {
  width: 100%;
  min-height: min(30px, 8.34cqw);
  border: 1px solid rgba(120, 144, 156, 0.2);
  border-radius: var(--dashboard-node-radius);
  padding: min(4px, 1.12cqw) min(8px, 2.22cqw);
  background: rgba(255, 255, 255, 0.96);
  font-size: min(13px, 3.62cqw);
  line-height: 1.2;
}

.dashboard-home__shared-setting-choices {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.dashboard-home__shared-setting-choice {
  appearance: none;
  min-height: 30px;
  padding: 4px 10px;
  border-style: solid !important;
  border-width: 1px 1px 0.5px !important;
  border-color: rgba(188, 208, 234, 0.22) !important;
  border-radius: var(--dashboard-node-radius) !important;
  background: linear-gradient(180deg, rgba(247, 250, 255, 0.98), rgba(232, 240, 252, 0.94)) !important;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.76),
    0 -1px 0 rgba(167, 194, 226, 0.24) !important;
  color: #17365d !important;
  font-weight: 700;
}

.dashboard-home__shared-setting-choice.is-active {
  background: linear-gradient(180deg, rgba(255, 250, 247, 0.98), rgba(252, 239, 230, 0.95)) !important;
  color: #24547b !important;
}

.dashboard-home__shared-module-popup-body .dashboard-home__inline-button {
  align-self: flex-end;
  padding: min(8px, 2.22cqw) min(12px, 3.34cqw);
  font-size: min(13px, 3.62cqw);
  line-height: 1;
}

.dashboard-home__shared-module-note {
  color: var(--dashboard-muted);
  font-size: min(12px, 3.34cqw);
}

/* Weather and Pomodoro settings are body-level popups, so they must carry
   the resolved dashboard theme instead of relying on homepage inheritance. */
.dashboard-home__shared-module-popup:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) {
  --dashboard-node-radius: 8px;
  --dashboard-control-radius: 8px;
  --dashboard-text: #17365d;
  --dashboard-muted: #62758d;
  border-color: rgba(151, 181, 218, 0.48);
  background: rgba(241, 247, 255, 0.985);
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.78),
    0 18px 38px rgba(43, 73, 108, 0.22);
}

.dashboard-home__shared-module-popup:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-module-popup-header,
.dashboard-home__shared-module-popup:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-row {
  border: 1px solid rgba(176, 201, 231, 0.42);
  border-radius: var(--dashboard-node-radius);
  background: rgba(255, 255, 255, 0.76);
}

.dashboard-home__shared-module-popup:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-row {
  min-height: 42px;
  padding: 6px 8px;
}

.dashboard-home__shared-module-popup:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) :is(input, .dashboard-home__shared-setting-choice, .dashboard-home__inline-button, .dashboard-home__square-action) {
  border-color: rgba(155, 187, 225, 0.52) !important;
  border-radius: var(--dashboard-control-radius) !important;
  background: rgba(250, 253, 255, 0.94) !important;
  color: #17365d !important;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.7) !important;
}

.dashboard-home__shared-module-popup:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-choice.is-active {
  border-color: rgba(91, 148, 214, 0.7) !important;
  background: rgba(210, 230, 252, 0.96) !important;
}

.dashboard-home__shared-module-popup.dashboard-home--resolved-dark:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) {
  --dashboard-text: #eef5ff;
  --dashboard-muted: #b8c8dc;
  border-color: rgba(108, 143, 184, 0.58);
  background: rgba(24, 42, 63, 0.99);
  box-shadow:
    inset 0 0 0 2px rgba(109, 142, 180, 0.18),
    0 20px 42px rgba(0, 0, 0, 0.46);
}

.dashboard-home__shared-module-popup.dashboard-home--resolved-dark:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-module-popup-header,
.dashboard-home__shared-module-popup.dashboard-home--resolved-dark:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-row {
  border-color: rgba(105, 139, 178, 0.44);
  background: rgba(43, 65, 91, 0.9);
}

.dashboard-home__shared-module-popup.dashboard-home--resolved-dark:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) :is(input, .dashboard-home__shared-setting-choice, .dashboard-home__inline-button, .dashboard-home__square-action) {
  border-color: rgba(109, 145, 188, 0.58) !important;
  background: rgba(35, 55, 79, 0.98) !important;
  color: #eef5ff !important;
  box-shadow: inset 0 0 0 1px rgba(174, 201, 232, 0.08) !important;
}

.dashboard-home__shared-module-popup.dashboard-home--resolved-dark:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-choice.is-active {
  border-color: rgba(124, 174, 232, 0.82) !important;
  background: rgba(55, 92, 132, 0.98) !important;
}

.dashboard-home__shared-module-popup.dashboard-home--skin-island:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) {
  --dashboard-text: #56351f;
  --dashboard-muted: #86613d;
  border-color: #7dbb85;
  background: #edf3d8;
  box-shadow:
    inset 0 0 0 2px rgba(255, 253, 242, 0.9),
    0 18px 38px rgba(92, 65, 35, 0.24);
}

.dashboard-home__shared-module-popup.dashboard-home--skin-island:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-module-popup-header {
  border-color: #b77738;
  background: #e7ad67;
}

.dashboard-home__shared-module-popup.dashboard-home--skin-island:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-row {
  border-color: rgba(105, 169, 112, 0.58);
  background: #fffdf2;
}

.dashboard-home__shared-module-popup.dashboard-home--skin-island:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) :is(input, .dashboard-home__shared-setting-choice, .dashboard-home__inline-button, .dashboard-home__square-action) {
  border-color: #a87642 !important;
  background: #fffdf2 !important;
  color: #56351f !important;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.66) !important;
}

.dashboard-home__shared-module-popup.dashboard-home--skin-island:is(
  .dashboard-home__shared-module-popup--weather,
  .dashboard-home__shared-module-popup--pomodoro
) .dashboard-home__shared-setting-choice.is-active {
  border-color: #5da56b !important;
  background: #dcefc8 !important;
  color: #315d35 !important;
}

/* Shared module radius unification: match the 8px node radius used by the main sections. */
.dashboard-home__shared-module,
.dashboard-home__calendar-today,
.dashboard-home__calendar-month,
.dashboard-home__weather-left,
.dashboard-home__weather-right,
.dashboard-home__countdown-primary,
.dashboard-home__countdown-secondary,
.dashboard-home__countdown-note {
  border-radius: var(--dashboard-node-radius);
}

.dashboard-home__shared-module-icon,
.dashboard-home__calendar-today-seal,
.dashboard-home__calendar-month-button,
.dashboard-home__calendar-day.is-today,
.dashboard-home__weather-location-button,
.dashboard-home__weather-current,
.dashboard-home__weather-metric,
.dashboard-home__weather-metric-icon,
.dashboard-home__weather-sun > div,
.dashboard-home__weather-sun span,
.dashboard-home__weather-forecast-day,
.dashboard-home__countdown-primary-icon-button,
.dashboard-home__countdown-tile,
.dashboard-home__countdown-tile-top > span,
.dashboard-home__countdown-note small,
.dashboard-home__countdown-pin-note,
.dashboard-home__countdown-list-item {
  border-radius: var(--dashboard-node-radius);
}

.dashboard-home__shared-module-settings,
.dashboard-home__shared-module-popup,
.dashboard-home__shared-module-popup-header,
.dashboard-home__shared-setting-row input,
.dashboard-home__countdown-pin {
  border-radius: var(--dashboard-control-radius);
}

/* Progress and daily schedule share one responsive planning row. */
.dashboard-home__planning-row {
  --planning-glass-border: rgba(195, 212, 235, 0.24);
  --planning-glass-surface: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(239, 246, 255, 0.94));
  --planning-glass-panel: linear-gradient(180deg, rgba(248, 251, 255, 0.98), rgba(237, 244, 253, 0.94));
  --planning-glass-card: linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(244, 249, 255, 0.92));
  --planning-glass-highlight: rgba(255, 255, 255, 0.78);
  --planning-glass-edge: rgba(167, 194, 226, 0.24);
  --planning-glass-shell:
    inset 0 0 0 2px var(--planning-glass-highlight),
    0 -1px 0 0 var(--planning-glass-edge);
  display: grid !important;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  align-items: stretch;
  column-gap: var(--dashboard-planning-gap) !important;
  row-gap: var(--dashboard-planning-gap) !important;
  min-width: 0;
  margin: 0 0 var(--dashboard-front-stack-gap) !important;
  overflow-anchor: none;
}

.dashboard-home__planning-row > .dashboard-home__progress-section {
  grid-column: span 15;
}

.dashboard-home__planning-row > .dashboard-home__schedule-section {
  grid-column: span 9;
}

.dashboard-home__planning-row.is-single-visible > .dashboard-home__progress-section,
.dashboard-home__planning-row.is-single-visible > .dashboard-home__schedule-section {
  grid-column: 1 / -1;
}

.dashboard-home__planning-row.is-row-hidden {
  display: none !important;
}

.dashboard-home__planning-row > .dashboard-home__progress-section,
.dashboard-home__planning-row > .dashboard-home__schedule-section {
  min-width: 0;
  height: auto;
  align-self: stretch;
  margin: 0;
}

@media (max-width: 960px) {
  .dashboard-home__planning-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .dashboard-home__planning-row > .dashboard-home__progress-section,
  .dashboard-home__planning-row > .dashboard-home__schedule-section {
    grid-column: 1 / -1;
  }
}

/* Final shared-module shell: keep every outer card visually identical. */
.dashboard-home .dashboard-home__shared-modules > .dashboard-home__shared-module {
  box-sizing: border-box;
  border-style: solid !important;
  border-width: 1px 1px 0.5px !important;
  border-color: rgba(174, 198, 228, 0.3) !important;
  border-radius: var(--dashboard-node-radius) !important;
  clip-path: inset(0 round var(--dashboard-node-radius));
  background-color: #f1f6fc !important;
  background-image: linear-gradient(180deg, rgba(248, 251, 255, 0.98), rgba(237, 244, 253, 0.94)) !important;
  background-clip: padding-box;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.78),
    0 -1px 0 0 rgba(144, 178, 218, 0.2) !important;
  overflow: hidden !important;
}
/* END Shared Modules Shared Block: shell grid, popup, planning row, and final shell overrides */

/* BEGIN Recent Files Shared Block: shell and module styles */
.dashboard-home__shared-module--recent {
  --recent-surface-gradient: linear-gradient(160deg, rgba(250, 252, 255, 0.98), rgba(233, 241, 253, 0.94));
  --recent-glass-highlight: rgba(255, 255, 255, 0.76);
  --recent-glass-edge: rgba(167, 194, 226, 0.24);
  container-type: inline-size;
  padding: 0;
  border-color: rgba(182, 204, 233, 0.34);
  background-color: #f1f6fc !important;
  background-image: var(--recent-surface-gradient) !important;
  box-shadow:
    inset 0 0 0 2px var(--recent-glass-highlight),
    0 -1px 0 0 var(--recent-glass-edge) !important;
}

/* Keep paint resets on the fixed recent-files nodes only. */
.dashboard-home__shared-module--recent,
.dashboard-home__recent-files-title,
.dashboard-home__recent-files-tabs,
.dashboard-home__recent-files-tab,
.dashboard-home__recent-files-item,
.dashboard-home__recent-files-item-icon,
.dashboard-home__recent-files-item-tag,
.dashboard-home__recent-files-empty {
  box-shadow: none !important;
}

.dashboard-home__recent-files-title,
.dashboard-home__recent-files-tab,
.dashboard-home__recent-files-item-title,
.dashboard-home__recent-files-item-meta,
.dashboard-home__recent-files-item-tag,
.dashboard-home__recent-files-empty {
  text-shadow: none !important;
}

.dashboard-home__recent-files-host {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: min(10px, 2.15cqw);
  height: 100%;
  min-height: 0;
  padding: min(14px, 3cqw);
  box-sizing: border-box;
  contain: layout style;
}

.dashboard-home__recent-files-header {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.55fr);
  align-items: center;
  gap: min(12px, 2.6cqw);
  min-height: min(64px, 12.8cqw);
}

.dashboard-home__recent-files-title {
  display: flex;
  align-items: center;
  gap: min(8px, 1.72cqw);
  min-width: 0;
  height: min(64px, 12.8cqw);
  padding: 0 min(16px, 3.45cqw);
  border: 1px solid rgba(195, 212, 235, 0.24);
  border-radius: var(--dashboard-node-radius);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(244, 248, 255, 0.9));
  box-shadow:
    inset 0 0 0 2px var(--recent-glass-highlight),
    0 -1px 0 0 var(--recent-glass-edge) !important;
  color: #17365d;
  font-size: min(calc(19.2px * var(--dashboard-recent-title-font-scale, 1)), calc(4.15cqw * var(--dashboard-recent-title-font-scale, 1)));
  font-weight: 800;
  line-height: 1.1;
  overflow: hidden;
}

.dashboard-home__recent-files-title-icon {
  display: grid;
  place-items: center;
  width: min(28px, 6.05cqw);
  height: min(28px, 6.05cqw);
  flex: 0 0 auto;
  font-size: min(19.2px, 4.15cqw);
  line-height: 1;
  filter: none !important;
}

.dashboard-home__recent-files-title-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__recent-files-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: min(6px, 1.3cqw);
  width: 100%;
  min-width: 0;
  height: min(64px, 12.8cqw);
  padding: min(7px, 1.5cqw);
  align-items: stretch;
  box-sizing: border-box;
  border: 1px solid rgba(195, 212, 235, 0.24);
  border-radius: var(--dashboard-node-radius);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(244, 248, 255, 0.9));
  box-shadow:
    inset 0 0 0 2px var(--recent-glass-highlight),
    0 -1px 0 0 var(--recent-glass-edge) !important;
}

.dashboard-home__recent-files-tab {
  display: grid;
  place-items: center;
  align-self: stretch;
  min-width: 0;
  min-height: 0;
  height: 100%;
  box-sizing: border-box;
  padding: 0;
  border: 0;
  border-radius: var(--dashboard-node-radius);
  background: transparent;
  color: #5d6f83;
  font-size: min(calc(15.6px * var(--dashboard-recent-tab-font-scale, 1)), calc(3.36cqw * var(--dashboard-recent-tab-font-scale, 1)));
  font-weight: 800;
  line-height: 1;
  text-transform: lowercase;
  cursor: pointer;
}

.dashboard-home__recent-files-tab.is-active {
  background: linear-gradient(180deg, rgba(238, 245, 255, 0.98), rgba(223, 236, 255, 0.92));
  color: #2b67c2;
  box-shadow:
    inset 0 0 0 2px rgba(112, 157, 226, 0.24),
    0 -1px 0 0 rgba(101, 145, 214, 0.18) !important;
}

.dashboard-home__recent-files-list {
  display: grid;
  grid-template-rows: repeat(5, minmax(0, 1fr));
  gap: min(8px, 1.72cqw);
  height: 100%;
  min-height: 0;
  align-content: stretch;
  contain: layout style;
}

.dashboard-home__recent-files-item {
  display: grid;
  grid-template-columns: min(54px, 11.65cqw) minmax(0, 1fr) auto;
  align-items: center;
  gap: min(15px, 3.25cqw);
  width: 100%;
  min-width: 0;
  min-height: 0;
  height: 100%;
  box-sizing: border-box;
  padding: min(8px, 1.72cqw) min(10px, 2.15cqw);
  border: 1px solid rgba(195, 212, 235, 0.22);
  border-radius: var(--dashboard-node-radius);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(246, 249, 255, 0.94));
  box-shadow:
    inset 0 0 0 2px var(--recent-glass-highlight),
    0 -1px 0 0 var(--recent-glass-edge) !important;
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  contain: layout style;
}

.dashboard-home__recent-files-item-icon {
  display: grid;
  place-items: center;
  width: min(50px, 10.8cqw);
  height: min(50px, 10.8cqw);
  border: 1px solid rgba(203, 219, 239, 0.28);
  border-radius: var(--dashboard-node-radius);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(239, 245, 255, 0.92));
  box-shadow:
    inset 0 0 0 2px var(--recent-glass-highlight),
    0 -1px 0 0 var(--recent-glass-edge) !important;
}

.dashboard-home__recent-files-item-icon-glyph {
  font-size: min(25.2px, 5.46cqw);
  line-height: 1;
  opacity: 0.9;
}

.dashboard-home__recent-files-item-body {
  display: grid;
  grid-template-rows: max-content max-content;
  align-content: center;
  gap: min(3px, 0.65cqw);
  min-width: 0;
