  --motto-glass-highlight: rgba(255, 255, 255, 0.76);
  --motto-glass-edge: rgba(167, 194, 226, 0.24);
  background-color: #f1f6fc !important;
  background-image: var(--motto-surface-gradient) !important;
}

.dashboard-home__shared-module--motto,
.dashboard-home__motto-home-shell,
.dashboard-home__motto-home-compact,
.dashboard-home__motto-home-manager,
.dashboard-home__motto-home-manager-header,
.dashboard-home__motto-home-panel-button,
.dashboard-home__motto-home-source-select,
.dashboard-home__motto-home-left,
.dashboard-home__motto-home-right,
.dashboard-home__motto-home-group-tabs,
.dashboard-home__motto-home-group-tab,
.dashboard-home__motto-home-panel,
.dashboard-home__motto-home-active-title-input,
