/* BEGIN Countdown Shared Block: home shell and module styles */
.dashboard-home__shared-module--countdown {
  --countdown-surface-color: #f1f6fc;
  --countdown-surface-gradient: linear-gradient(160deg, rgba(250, 252, 255, 0.98), rgba(233, 241, 253, 0.94));
  --countdown-title-color: #173e68;
  --countdown-primary-muted-color: #5e7da0;
  --countdown-tile-muted-color: #6b87a4;
  --countdown-number-color: var(--countdown-accent, #4f8ee8);
  --countdown-unit-color: var(--countdown-accent, #4f8ee8);
  --countdown-note-color: #56718d;
  --countdown-panel-border: rgba(195, 212, 235, 0.24);
  --countdown-panel-bg: rgba(255, 255, 255, 0.54);
  --countdown-node-bg: rgba(250, 253, 255, 0.76);
  --countdown-icon-bg: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(239, 245, 255, 0.92));
  --countdown-icon-color: #17365d;
  --countdown-note-bg: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(246, 249, 255, 0.94));
  --countdown-final-border: rgba(195, 212, 235, 0.24);
  --countdown-glass-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.76), 0 -1px 0 0 rgba(167, 194, 226, 0.24);
  grid-column: span 4;
  container-type: inline-size;
  padding: 10px;
  background-color: var(--countdown-surface-color);
