/* Countdown home refinements: compact primary card, wider readable right-side rows. */
.dashboard-home__countdown-shell {
  grid-template-columns: minmax(0, 0.36fr) minmax(0, 0.64fr);
  --dashboard-countdown-home-gap: clamp(6px, 0.7cqw, 10px);
  --dashboard-countdown-card-radius: clamp(10px, 1.25cqw, 14px);
  --dashboard-countdown-node-radius: clamp(8px, 1cqw, 12px);
  gap: var(--dashboard-countdown-home-gap);
  align-items: stretch;
}

.dashboard-home__countdown-primary {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  align-content: center;
  justify-items: center;
  gap: clamp(5px, 0.62cqw, 10px);
  width: 100%;
  height: 100%;
  aspect-ratio: auto;
  align-self: stretch;
  justify-self: stretch;
  padding: clamp(10px, 1cqw, 14px);
  border-radius: var(--dashboard-countdown-card-radius);
}

.dashboard-home__countdown-primary::after {
  display: none;
}

.dashboard-home__countdown-primary-number {
  align-self: center;
  justify-self: center;
}

.dashboard-home__countdown-primary-number strong {
  font-size: clamp(52px, 8.2cqw, 86px);
}

.dashboard-home__countdown-primary-icon-button {
  margin-bottom: clamp(2px, 0.3cqw, 5px);
}

.dashboard-home__countdown-primary-title,
.dashboard-home__countdown-primary-date,
.dashboard-home__countdown-primary-state {
  text-align: center;
}

.dashboard-home__countdown-primary-date {
  transform: translateY(-4px);
  margin-bottom: -4px;
}

.dashboard-home__countdown-secondary {
  grid-template-rows: repeat(4, minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  border-radius: var(--dashboard-countdown-node-radius);
}

.dashboard-home__countdown-tile {
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: minmax(0, 1fr);
  gap: clamp(6px, 0.65cqw, 10px);
  align-items: center;
  overflow: hidden;
  border-radius: var(--dashboard-countdown-node-radius);
}

.dashboard-home__countdown-tile-top {
  grid-row: 1;
  grid-template-columns: clamp(24px, 2.8cqw, 34px) minmax(0, 1fr);
  align-self: center;
}

.dashboard-home__countdown-tile-top > span {
  width: clamp(24px, 2.8cqw, 34px);
  height: clamp(24px, 2.8cqw, 34px);
}

.dashboard-home__countdown-tile-top strong,
.dashboard-home__countdown-tile-top small {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  line-height: 1.15;
}

.dashboard-home__countdown-tile-days {
  display: grid;
  grid-row: 1;
  align-self: center;
  justify-self: center;
  min-width: clamp(42px, 5.2cqw, 64px);
  text-align: center;
  place-items: center;
}

.dashboard-home__countdown-tile-days strong,
.dashboard-home__countdown-tile-days span {
  line-height: 1;
}

.dashboard-home__countdown-tile-state {
  display: none;
}

.dashboard-home__countdown-footer {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--dashboard-countdown-home-gap, clamp(6px, 0.7cqw, 10px));
  min-height: var(--dashboard-countdown-footer-height, 58px);
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.dashboard-home__countdown-note {
  display: grid;
  grid-template-columns: clamp(42px, 5.2cqw, 56px) minmax(0, 1fr);
  gap: clamp(5px, 0.65cqw, 9px);
  align-items: center;
  min-width: 0;
  padding: clamp(6px, 0.8cqw, 10px);
  border: 1px solid var(--countdown-final-border);
  border-radius: var(--dashboard-countdown-node-radius);
  background: var(--countdown-note-bg);
  box-shadow: var(--countdown-glass-shadow);
}

.dashboard-home__countdown-note small {
  display: grid;
  place-items: center;
  width: clamp(42px, 5.2cqw, 56px);
  min-width: 0;
  height: clamp(24px, 3cqw, 34px);
  border-radius: var(--dashboard-countdown-node-radius);
  background: var(--countdown-icon-bg);
  color: var(--countdown-icon-color);
  font-weight: 700;
  text-align: center;
}

.dashboard-home__countdown-note strong {
  display: grid;
  place-items: center;
  min-width: 0;
  width: 100%;
  height: 100%;
  color: var(--countdown-note-color) !important;
  line-height: 1.25;
  text-align: center;
  white-space: normal;
}
