@media (max-width: 1200px) {
  .dashboard-home__triple-task-wrap {
    grid-template-columns: 1fr;
  }

  .dashboard-home__board-a-scroll {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 1100px) {
  .dashboard-home__top-grid,
  .dashboard-home__grid,
  .dashboard-home__adaptive-split {
    grid-template-columns: 1fr;
  }

  .dashboard-home__board-a-scroll {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .dashboard-home__board-task-wrap,
  .dashboard-home__board-a-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
.dashboard-home {
    padding: 14px;
    scroll-padding-bottom: calc(14px + var(--dashboard-scroll-toolbar-clearance));
  }

  /* 目录区与画板区：标题控制区分成上下两行，避免移动端互相挤压。 */
  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__nav-summary {
    flex-direction: column;
    align-items: stretch;
  }

  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__excalidraw-title-wrap {
    width: 100%;
    flex: 0 0 auto;
  }

  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__card-controls {
    width: 100%;
    margin-left: 0;
    justify-content: flex-end;
  }

  /* 工具栏保留原按钮顺序，空间不足时在卡片内部自动换行。 */
  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__excalidraw-toolbar,
  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__excalidraw-toolbar-group {
    flex-wrap: wrap;
    align-content: flex-start;
    max-width: 100%;
  }

  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__excalidraw-toolbar-group--right {
    margin-left: 0;
  }

  /* 每次完整显示一个分组；分组内部原有行布局不变，左右滑动查看其他分组。 */
  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__nav-groups {
    grid-template-columns: none;
    grid-auto-flow: column;
    grid-auto-columns: 100%;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x proximity;
    touch-action: pan-x pan-y;
  }

  .dashboard-home .dashboard-home__top-grid > .dashboard-home__excalidraw-card .dashboard-home__nav-groups > .dashboard-home__nav-group {
    min-width: 0;
    scroll-snap-align: start;
  }

  .dashboard-home__kanban-scroll {
    grid-auto-columns: minmax(280px, 90vw);
  }

  .dashboard-home__board-a-scroll {
    grid-template-columns: 1fr;
  }

  .dashboard-home__note-node {
    width: min(180px, calc(100% - 24px));
  }
}

/* Skip painting heavy dashboard regions while they are outside the viewport. */
@supports (content-visibility: auto) {
  .dashboard-home__task-row,
  .dashboard-home__note-card--c,
  .dashboard-home__nav-item-card {
    content-visibility: auto;
    contain-intrinsic-block-size: auto 58px;
  }

  .dashboard-home__event-module {
    content-visibility: visible;
    contain-intrinsic-block-size: none;
  }

  /* 日程列表收缩时，目录与画板会进入视口。它们不能继续使用 58px 的
     视口外估算高度，否则 Chromium 在首次绘制真实内容时会让下方界面跳动。 */
  .dashboard-home__navigation-directory-card .dashboard-home__nav-item-card,
  .dashboard-home__excalidraw-card .dashboard-home__nav-item-card {
    content-visibility: visible;
    contain-intrinsic-block-size: none;
  }

  .dashboard-home__card[data-section="board-a"] .dashboard-home__board-a-task-row {
    content-visibility: visible;
    contain-intrinsic-block-size: none;
  }

  .dashboard-home__card[data-section="notes"] .dashboard-home__note-card--c {
    content-visibility: visible;
    contain-intrinsic-block-size: none;
  }

  .dashboard-home__card[data-section="notes"] .dashboard-home__note-card--c :is(
    .dashboard-home__leaf-body,
    .dashboard-home__editable-wrap,
    .dashboard-home__editable-display,
    .dashboard-home__editable-markdown,
    .dashboard-home__note-meta-stack,
    .dashboard-home__note-status-button
  ) {
    content-visibility: visible !important;
    contain-intrinsic-block-size: none !important;
  }

  .dashboard-home__card[data-section="checkins"] .dashboard-home__checkin-task-row {
    content-visibility: visible;
    contain-intrinsic-block-size: none;
  }

  .dashboard-home__card[data-section="checkins"] .dashboard-home__checkin-task-row :is(
    .dashboard-home__leaf-body,
    .dashboard-home__editable-wrap,
    .dashboard-home__editable-display,
    .dashboard-home__editable-markdown
  ) {
    content-visibility: visible !important;
    contain-intrinsic-block-size: none !important;
  }

  .dashboard-home__task-row:hover,
  .dashboard-home__task-row:focus-within,
  .dashboard-home__note-card--c:hover,
  .dashboard-home__note-card--c:focus-within {
    content-visibility: visible;
  }
}

.dashboard-home__card[data-section="notes"] .dashboard-home__note-card--c :is(
  .dashboard-home__leaf-body,
  .dashboard-home__editable-display,
  .dashboard-home__editable-markdown,
  .dashboard-home__note-meta-stack,
  .dashboard-home__note-status-button
) {
  contain: none;
}

