.dashboard-home__tutorial-visual {
  overflow: hidden;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--dashboard-node-radius);
  background: var(--background-secondary);
}

.dashboard-home__tutorial-svg {
  display: block;
  width: 100%;
  height: auto;
}

.tutorial-svg__shell {
  fill: var(--background-primary);
  stroke: var(--background-modifier-border);
  stroke-width: 2;
}

.tutorial-svg__banner {
  fill: #dff4ff;
  stroke: #91b9d2;
  stroke-width: 2;
}

.tutorial-svg__card {
  stroke: var(--background-modifier-border);
  stroke-width: 2;
}

.tutorial-svg__card--1 { fill: #fff9e8; }
.tutorial-svg__card--2 { fill: #e5f1bd; }
.tutorial-svg__card--3 { fill: #f7e8ed; }
.tutorial-svg__icon { fill: #70bd8e; }
.tutorial-svg__line {
  stroke: #6f7f8d;
  stroke-width: 5;
  stroke-linecap: round;
}
.tutorial-svg__line.is-muted {
  opacity: 0.45;
  stroke-width: 3;
}
.tutorial-svg__toolbar {
  fill: #e5a257;
  stroke: #b97835;
  stroke-width: 2;
}
.tutorial-svg__toolbar-button {
  fill: #fffdf2;
  stroke: #dfc474;
  stroke-width: 2;
}

.dashboard-home__tutorial-title {
  font-size: 24px;
  text-align: center;
}

.dashboard-home__tutorial-description {
  min-height: 44px;
  font-size: 15px;
  line-height: 1.55;
  text-align: center;
}

.dashboard-home__tutorial-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
}

.dashboard-home__tutorial-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--background-modifier-border);
}

.dashboard-home__tutorial-dot.is-active {
  width: 22px;
  border-radius: var(--dashboard-node-radius);
  background: var(--interactive-accent);
}

.dashboard-home__tutorial-actions {
  justify-content: flex-end;
  flex-wrap: wrap;
}

.dashboard-home__tutorial-button {
  min-height: 38px;
  padding: 6px 16px;
  border-radius: var(--dashboard-node-radius) !important;
}

.dashboard-home__tutorial-button.is-secondary {
  margin-right: auto;
}

.dashboard-home__tutorial-button.is-primary {
  background: var(--interactive-accent) !important;
  color: var(--text-on-accent) !important;
}

@media (max-width: 760px) {
  .dashboard-home__tutorial-modal .modal-content {
    gap: 10px;
    padding: 14px;
  }

  .dashboard-home__tutorial-title {
    font-size: 20px;
  }
}

.dashboard-home.dashboard-home--resolved-dark .dashboard-home__license-preview-panel {
  background: #22364e;
  border-color: #4a6688;
}

.dashboard-home.dashboard-home--skin-island .dashboard-home__license-preview-panel {
  background: #fffdf2;
  border-color: #b78a4a;
  color: #57361f;
}

