/* Mobile planner views keep their toolbar fixed and scroll only the actual view body. */
@media (max-width: 760px) {
  .dashboard-home .dashboard-home__planner-content:is(.is-week, .is-month, .is-year, .is-tasks) {
    min-width: 0;
    overflow: hidden;
  }

  .dashboard-home .dashboard-home__planner-content.is-day .dashboard-home__planner-day-timeline {
    min-width: 0;
    overflow-x: hidden;
    overflow-y: auto;
  }

  .dashboard-home .dashboard-home__planner-content.is-day :is(
    .dashboard-home__planner-day-lane,
    .dashboard-home__planner-hours
  ) {
    width: 100%;
    min-width: 0;
  }

  .dashboard-home .dashboard-home__planner-content.is-day .dashboard-home__planner-hour {
    height: auto;
    min-height: 120px;
  }

  .dashboard-home .dashboard-home__planner-content.is-day .dashboard-home__planner-hour-slot {
    height: auto;
    min-height: 120px;
  }

  .dashboard-home .dashboard-home__planner-content.is-day .dashboard-home__planner-scheduled-blocks {
    position: relative;
    inset: auto;
    display: flex;
    flex-direction: column;
    gap: 4px;
    box-sizing: border-box;
    width: 100%;
    padding: 4px 5px 5px 48px;
    overflow: visible;
  }

  .dashboard-home .dashboard-home__planner-content.is-day .dashboard-home__planner-scheduled-blocks > .dashboard-home__planner-entry.is-scheduled-block {
    position: relative;
    top: auto !important;
    left: auto !important;
    width: 100% !important;
    height: auto !important;
    min-height: 42px;
    flex: 0 0 auto;
  }

  .dashboard-home .dashboard-home__planner-content.is-week > .dashboard-home__planner-week {
    grid-template-columns: repeat(7, minmax(138px, 1fr));
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-gutter: stable;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-x pan-y;
  }

  .dashboard-home .dashboard-home__planner-content.is-week .dashboard-home__planner-repeat-group {
    grid-column: 1 / -1;
  }

  .dashboard-home .dashboard-home__planner-content.is-week .dashboard-home__planner-repeat-group-days {
    grid-template-columns: repeat(7, minmax(138px, 1fr));
  }

  .dashboard-home .dashboard-home__planner-content.is-week > .dashboard-home__planner-week-timeline {
    width: 100%;
    min-width: 0;
  }

  .dashboard-home .dashboard-home__planner-content.is-month > .dashboard-home__planner-month {
    grid-template-columns: repeat(7, minmax(138px, 1fr));
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-gutter: stable;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-x pan-y;
  }

  .dashboard-home .dashboard-home__planner-content.is-year > .dashboard-home__planner-year {
    grid-template-columns: repeat(var(--planner-year-columns, 6), minmax(220px, 1fr));
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-gutter: stable;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-x pan-y;
  }

  .dashboard-home .dashboard-home__planner-content.is-year .dashboard-home__planner-year-group-row {
    grid-column: 1 / -1;
  }

  .dashboard-home .dashboard-home__planner-content.is-year .dashboard-home__planner-year-group-months {
    grid-template-columns: repeat(var(--planner-year-columns, 6), minmax(220px, 1fr));
  }

  .dashboard-home .dashboard-home__planner-content.is-tasks > .dashboard-home__planner-all-tasks {
    grid-template-columns: repeat(3, minmax(300px, 1fr));
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-gutter: stable;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-x pan-y;
  }
}

/* Shared dark-theme text selection: keep selected text readable everywhere in A_Home. */
.dashboard-home.dashboard-home--resolved-dark *::selection,
.dashboard-home.dashboard-home--theme-dark.dashboard-home--skin-default *::selection,
body.theme-dark .dashboard-home.dashboard-home--theme-follow.dashboard-home--skin-default *::selection,
[class*="dashboard-home__"][class*="--resolved-dark"] *::selection {
  background-color: #b7d7ff !important;
  color: #10243a !important;
  -webkit-text-fill-color: #10243a !important;
  text-shadow: none !important;
}
/* 第四分区：左侧分组索引 + 右侧六级递归任务工作区 */
.dashboard-home__checkins-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
  margin-top: 8px;
  min-height: 420px;
  flex: 1 1 auto;
  align-self: stretch;
}

.dashboard-home__checkins-groups,
.dashboard-home__checkins-content {
  min-width: 0;
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  background: var(--background-secondary);
  overflow: hidden;
}

.dashboard-home__checkins-groups { padding: 10px; }
.dashboard-home__checkins-content { padding: 10px; }
.dashboard-home__checkins-content {
  display: flex;
  flex-direction: column;
  align-self: stretch;
  min-height: 0;
  height: 100%;
}
.dashboard-home__checkins-pane-title,
.dashboard-home__checkins-content-header,
.dashboard-home__checkins-level-header {
  border-radius: 10px;
}
.dashboard-home__checkins-pane-title {
  padding: 9px 10px;
  text-align: center;
  font-weight: 700;
  background: var(--background-primary-alt);
}
.dashboard-home__checkins-group-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  min-width: 0;
}
.dashboard-home__checkins-pane-title--with-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
