/* Standalone pomodoro drawer: preserves timer data while isolating manager layout from the home card. */
.dashboard-pomodoro-drawer-v2-layer {
  --dashboard-node-radius: 8px;
  --dashboard-pomodoro-drawer-edge: 88px;
  position: fixed;
  inset: 0;
  z-index: 10020;
  overflow: hidden;
  pointer-events: none;
}

.dashboard-pomodoro-drawer-v2__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(20, 34, 28, 0.18);
  pointer-events: auto;
}

.dashboard-pomodoro-drawer-v2 {
  position: absolute;
  top: 88px;
  bottom: 88px;
  width: 480px;
  max-width: calc(100vw - 176px);
  box-sizing: border-box;
  border: 1px solid rgba(195, 212, 235, 0.24);
  border-radius: 8px;
  background: #f3f8fe;
  box-shadow: 0 12px 30px rgba(44, 68, 49, 0.22);
  overflow: hidden;
  pointer-events: auto;
  contain: none;
  container-type: normal;
  transform: none;
}

