  left: var(--dashboard-pomodoro-drawer-edge);
}

.dashboard-pomodoro-drawer-v2-layer.is-right .dashboard-pomodoro-drawer-v2 {
  right: var(--dashboard-pomodoro-drawer-edge);
}

.dashboard-pomodoro-drawer-v2__manager {
  position: static;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 8px;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  padding: 10px;
  box-sizing: border-box;
  background: #f3f8fe;
  overflow: hidden;
  contain: none;
  container-type: normal;
}

.dashboard-pomodoro-drawer-v2__content {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  width: 100%;
  height: 100%;
  max-height: 100%;
  min-width: 0;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
